@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MainScreen(rootNavController: NavHostController) {

 val TAG = "MainScreen"
 val context = LocalContext.current
 val navController = rememberNavController()
 val navBackStackEntry by navController.currentBackStackEntryAsState()
 val currentRoute = navBackStackEntry?.destination?.route
 val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
 val scope = rememberCoroutineScope()

 val vm: MainScreenVM = viewModel()
 val showLocationSheet by vm.showLocationSheet.collectAsState()
 val sharedViewModel = remember { GlobalViewModelProvider.get(SharedViewModel::class.java) }

 val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)

 val onClickProfile: () -> Unit = {
 scope.launch {
 drawerState.open()
 }
 }

 /** Retry Dashboard API */
 val retryDashboardApi: () -> Unit = {
 when (sharedViewModel.currentAddress) {
 is AddressData.Success -> {
 val address = sharedViewModel.currentAddress as AddressData.Success
 vm.retryDashboardApi(address.address.latitude, address.address.longitude)
 }

 is AddressData.Failure -> {
 vm.retryDashboardApi(0.0, 0.0)
 }
 }
 }

 /** Logout from side drawer */
 val doLogOUt: () -> Unit = {
 InAppStore.saveBoolean(context = context, key = AppKey.IS_LOGIN, value = false)
 InAppStore.saveString(context = context, key = AppKey.FCM_TOKEN, value = "")
 AppStorage.clearToken()
 FirebaseUtils.deleteFCMToken()
 rootNavController.navigate(Screen.LoginRegisterScreen.route)
 }

 LaunchedEffect(Unit) {
 FirebaseMessaging.getInstance().token
 .addOnCompleteListener { task ->
 if (!task.isSuccessful) {
 Log.w(TAG, "Fetching FCM registration token failed", task.exception)
 return@addOnCompleteListener
 }
 val token = task.result
 Log.d(TAG, "Token: $token")
 }
 }

 LaunchedEffect(Unit) {

 when (sharedViewModel.currentAddress) {
 is AddressData.Success -> {
 val address = sharedViewModel.currentAddress as AddressData.Success
 vm.getDashboardData(address.address.latitude, address.address.longitude)
 }

 is AddressData.Failure -> {
 // Todo
 vm.getDashboardData(0.0, 0.0)
 }
 }
 vm.getCategoryList()
 }

 LaunchedEffect(showLocationSheet) {
 if (showLocationSheet == true) {
 sheetState.show()
 } else {
 sheetState.hide()
 }
 }

 ModalNavigationDrawer(
 drawerState = drawerState, drawerContent = {
 DrawerContent(
 onClickCreateBusiness = {
 scope.launch {
 drawerState.close()
 }
 CreateBusinessConfirmationSheet.show()
 },
 onClickLogoutButton = {
 scope.launch {
 drawerState.close()
 }
 LogoutSheet.show()
 }
 )
 }, gesturesEnabled = true
 ) {
 Scaffold(
 bottomBar = { BottomBar(navController, currentRoute) }) { innerPadding ->

 NavHost(
 navController = navController,
 startDestination = Routes.HOME,
 modifier = Modifier.padding(bottom = innerPadding.calculateBottomPadding())
 ) {
 composable(route = Routes.HOME) {
 HomeScreen(
 navController = navController,
 viewModel = vm,
 onClickProfile = { onClickProfile() })
 }
 composable(route = Routes.CATEGORY) { CategoryScreen(vm = vm) }
 composable(Routes.BOOKING) { BookingScreen(vm = vm) }
 composable(Routes.CHAT) { ChatScreen(vm = vm) }
 }
 }
 }

 if (showLocationSheet) {
 LocationSelectionSheet(
 sheetState = sheetState,
 onDismiss = { vm.onClickLocationSheet(false) },
