 var updatedList = _serviceList.value + newData
 _serviceList.value = updatedList
 _serviceListResponse.value = ApiReasponse.Success(updatedList)
 // Check if more data exists
 hasMoreData = newData.size == pageSize
 if (hasMoreData) currentPage++
 } else {
 _serviceListResponse.value = ApiReasponse.Failed(result.message)
 }
 } catch (e: Exception) {
 Log.e(TAG, "Exception: ${e.message}")
 _serviceListResponse.value = ApiReasponse.Failed(e.message.toString())
 } finally {
 isLoading = false
 }
 }
 }
}

